function diasHastaMasCalido(temps) {
  const res = new Array(temps.length).fill(0);
  const pila = [];
  for (let i = 0; i < temps.length; i++) {
    while (pila.length && temps[pila.at(-1)] < temps[i]) {
      const j = pila.pop();
      res[j] = i - j;
    }
    pila.push(i);
  }
  return res;
}

solution.python:
def diasHastaMasCalido(temps):
    res = [0] * len(temps)
    pila = []
    for i, t in enumerate(temps):
        while pila and temps[pila[-1]] < t:
            j = pila.pop()
            res[j] = i - j
        pila.append(i)
    return res
